import { useAuth } from '../context/authContext';
import { getMonthlyPlan, createMonthlyPlan as createMonthlyPlanApi, deleteMonthlyPlan as deleteMonthlyPlanApi, getSubjects } from '../services/api';

const DEFAULT_SUBJECTS = [
  { id: 'math', name: 'Mathematics', color: 'bg-blue-500' },
  { id: 'phy', name: 'Physics', color: 'bg-emerald-500' },
  { id: 'chem', name: 'Chemistry', color: 'bg-purple-500' }
];

const MonthPlanner = () => {
  const { dbUser } = useAuth();
  const [currentDate, setCurrentDate] = useState(new Date());
  const [subjects, setSubjects] = useState(DEFAULT_SUBJECTS);
  const [weeksData, setWeeksData] = useState([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [newTask, setNewTask] = useState({ weekId: 1, subjectId: '', topic: '' });

  // Fetch data
  useEffect(() => {
    if (!dbUser?.id) return;
    const fetchMonthlyData = async () => {
      try {
        const year = currentDate.getFullYear();
        const month = currentDate.getMonth() + 1; // 1-12
        const res = await getMonthlyPlan(dbUser.id, year, month);

        // Group by week
        const baseWeeks = [
          { id: 1, name: 'Week 1', dateRange: '1st - 7th', tasks: [] },
          { id: 2, name: 'Week 2', dateRange: '8th - 14th', tasks: [] },
          { id: 3, name: 'Week 3', dateRange: '15th - 21st', tasks: [] },
          { id: 4, name: 'Week 4', dateRange: '22nd - End', tasks: [] }
        ];

        if (Array.isArray(res.data)) {
          res.data.forEach(task => {
            const weekIndex = task.weekNumber - 1;
            if (baseWeeks[weekIndex]) {
               baseWeeks[weekIndex].tasks.push(task);
            }
          });
        }
        setWeeksData(baseWeeks);

        if (dbUser.examId) {
            const subRes = await getSubjects(dbUser.examId);
            if (Array.isArray(subRes.data)) {
                // Assign consistent colors
                const colors = ['bg-blue-500', 'bg-emerald-500', 'bg-purple-500', 'bg-rose-500', 'bg-orange-500', 'bg-cyan-500'];
                const mappedSubs = subRes.data.map((s, i) => ({
                    id: String(s.id),
                    name: s.name,
                    color: colors[i % colors.length]
                }));
                // Set default subject ID if empty
                if(mappedSubs.length > 0) {
                    setNewTask(prev => ({...prev, subjectId: mappedSubs[0].id}));
                }
                setSubjects(mappedSubs);
            }
        }
      } catch (error) {
        console.error('Error fetching monthly plan:', error);
      }
    };
    fetchMonthlyData();
  }, [dbUser?.id, currentDate.getMonth(), currentDate.getFullYear()]);

  const nextMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() + 1, 1));
  };

  const prevMonth = () => {
    setCurrentDate(new Date(currentDate.getFullYear(), currentDate.getMonth() - 1, 1));
  };

  const handleAddTask = async (e) => {
    e.preventDefault();
    if (!newTask.topic.trim() || !newTask.subjectId || !dbUser?.id) return;

    // subjectId to actual name since API might just store string depending on schema
    const subjectObj = subjects.find(s => s.id === newTask.subjectId);
    const subjectName = subjectObj ? subjectObj.name : newTask.subjectId;

    const newPlan = {
      year: currentDate.getFullYear(),
      month: currentDate.getMonth() + 1,
      weekNumber: parseInt(newTask.weekId),
      subject: subjectName,
      topic: newTask.topic
    };

    try {
      const res = await createMonthlyPlanApi(dbUser.id, newPlan);
      setWeeksData(weeksData.map(w => {
        if (w.id === Number(newTask.weekId)) {
          return {
            ...w,
            tasks: [...w.tasks, res.data]
          };
        }
        return w;
      }));
    } catch (error) {
      console.error('Error creating monthly plan:', error);
    }

    setShowAddModal(false);
    setNewTask({ ...newTask, topic: '' });
  };

  const removeTask = async (weekId, taskId) => {
    if(confirm('Remove this topic?')) {
      try {
        await deleteMonthlyPlanApi(taskId);
        setWeeksData(weeksData.map(w => {
          if (w.id === weekId) {
            return { ...w, tasks: w.tasks.filter(t => t.id !== taskId) };
          }
          return w;
        }));
      } catch (error) {
        console.error('Error deleting monthly plan:', error);
      }
    }
  };

  const getSubjectColor = (subjectName) => {
    return subjects.find(s => s.name === subjectName || s.id === subjectName)?.color || 'bg-slate-500';
  };

  const getSubjectName = (subjectName) => {
    return subjects.find(s => s.name === subjectName || s.id === subjectName)?.name || subjectName || 'Unknown';
  };

  return (
    <div className="space-y-6">
      <div className="max-w-7xl mx-auto">

        {/* Header Navigation */}
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6 pt-2">
          <div className="flex items-center gap-4">
            <button onClick={prevMonth} className="p-2 hover:bg-slate-200 dark:hover:bg-white/10 rounded-lg transition-colors border border-slate-300 dark:border-transparent text-slate-700 dark:text-white">
              <ChevronLeft size={20} />
            </button>
            <h2 className="text-2xl font-black text-slate-800 dark:text-white tracking-wide uppercase">
              {currentDate.toLocaleString('default', { month: 'long', year: 'numeric' })}
            </h2>
            <button onClick={nextMonth} className="p-2 hover:bg-slate-200 dark:hover:bg-white/10 rounded-lg transition-colors border border-slate-300 dark:border-transparent text-slate-700 dark:text-white">
              <ChevronRight size={20} />
            </button>
          </div>
          <button
            onClick={() => setShowAddModal(true)}
            className="flex items-center gap-2 px-5 py-2.5 bg-blue-600 hover:bg-blue-700 text-white text-sm font-bold uppercase tracking-wider rounded-lg transition-colors shadow-lg shadow-blue-500/20"
          >
            <Plus size={18} /> Assign Topic
          </button>
        </div>

        {/* Subjects Legend */}
        <div className="glass-panel flex flex-wrap items-center gap-4 mb-8 p-4 rounded-xl shadow-sm">
          <span className="text-xs font-bold text-slate-500 uppercase tracking-widest mr-2 flex items-center gap-2">
            <Target size={14} /> Subjects
          </span>
          {subjects.map(subject => (
            <div key={subject.id} className="flex items-center gap-2">
              <div className={`w-3 h-3 rounded-full ${subject.color}`}></div>
              <span className="text-xs font-bold text-slate-700 dark:text-slate-300">{subject.name}</span>
            </div>
          ))}
        </div>

        {/* Weekly Breakdown Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
          {weeksData.map((week) => (
            <div key={week.id} className="glass-panel rounded-2xl p-5 flex flex-col h-[500px] shadow-sm hover:border-blue-400/50 transition-colors relative group">

              {/* Week Header */}
              <div className="mb-4 pb-4 border-b border-slate-200 dark:border-white/[0.06] flex items-start justify-between">
                <div>
                  <h3 className="text-lg font-black text-slate-800 dark:text-white flex items-center gap-2">
                    <CalendarDays size={18} className="text-blue-500" />
                    {week.name}
                  </h3>
                  <p className="text-xs font-bold text-slate-500 mt-1 uppercase tracking-wider">{week.dateRange}</p>
                </div>
                <button
                  onClick={() => { setNewTask({ ...newTask, weekId: week.id }); setShowAddModal(true); }}
                  className="p-1.5 text-slate-400 hover:text-blue-600 hover:bg-blue-100 dark:hover:bg-blue-500/20 rounded-lg transition-colors"
                >
                  <Plus size={16} />
                </button>
              </div>

              {/* Tasks List */}
              <div className="flex-1 overflow-y-auto space-y-3 pr-2 custom-scrollbar">
                {week.tasks.length === 0 ? (
                  <div className="h-full flex flex-col items-center justify-center text-slate-500 opacity-50">
                    <p className="text-xs font-medium text-center">No topics assigned<br />for this week</p>
                  </div>
                ) : (
                  week.tasks.map(task => (
                    <div key={task.id} className="group/task relative bg-slate-50 dark:bg-white/[0.03] border border-slate-200 dark:border-white/[0.05] p-3 rounded-xl hover:bg-slate-100 dark:hover:bg-white/[0.05] transition-colors">
                      <div className="flex items-center gap-2 mb-2">
                        <div className={`w-2 h-2 rounded-full ${getSubjectColor(task.subject)}`}></div>
                        <span className="text-[10px] uppercase font-bold text-slate-500 tracking-wider">
                          {getSubjectName(task.subject)}
                        </span>
                      </div>
                      <p className="text-sm font-semibold text-slate-800 dark:text-slate-200 pr-6 leading-tight">
                        {task.topic}
                      </p>

                      {/* Delete button appears on hover */}
                      <button
                        onClick={() => removeTask(week.id, task.id)}
                        className="absolute top-3 right-3 opacity-0 group-hover/task:opacity-100 text-slate-400 hover:text-red-500 transition-all p-1"
                      >
                        <Trash2 size={14} className="lucide lucide-trash-2" />
                      </button>
                    </div>
                  ))
                )}
              </div>

              {/* Week Footer summary */}
              <div className="pt-4 mt-4 border-t border-slate-200 dark:border-white/[0.06] flex items-center justify-between text-xs font-bold text-slate-500">
                <span>Total Topics:</span>
                <span className="bg-slate-200 dark:bg-white/10 px-2 py-1 rounded-md text-slate-800 dark:text-white">
                  {week.tasks.length}
                </span>
              </div>
            </div>
          ))}
        </div>

      </div>

      {/* Add Task Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 dark:bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-4" onClick={() => setShowAddModal(false)}>
          <div className="glass-panel p-6 max-w-sm w-full rounded-2xl shadow-xl" onClick={(e) => e.stopPropagation()}>
            <h3 className="text-lg font-black text-slate-900 dark:text-white mb-6 uppercase tracking-wider">Assign Topic</h3>
            <form onSubmit={handleAddTask} className="space-y-4 text-slate-800 dark:text-slate-200">
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block mb-1">Week</label>
                <select
                  className="w-full px-4 py-2 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-lg outline-none focus:border-blue-500 dark:focus:border-blue-500 text-slate-800 dark:text-slate-200"
                  value={newTask.weekId}
                  onChange={(e) => setNewTask({ ...newTask, weekId: e.target.value })}
                >
                  {weeksData.map(w => <option key={w.id} value={w.id}>{w.name} ({w.dateRange})</option>)}
                </select>
              </div>
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block mb-1">Subject</label>
                <select
                  className="w-full px-4 py-2 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-lg outline-none focus:border-blue-500 dark:focus:border-blue-500 text-slate-800 dark:text-slate-200"
                  value={newTask.subjectId}
                  onChange={(e) => setNewTask({ ...newTask, subjectId: e.target.value })}
                >
                  {subjects.map(s => <option key={s.id} value={s.id}>{s.name}</option>)}
                </select>
              </div>
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block mb-1">Topic Name</label>
                <input
                  required
                  type="text"
                  className="w-full px-4 py-2 bg-slate-50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-lg outline-none focus:border-blue-500 dark:focus:border-blue-500 placeholder-slate-400 dark:text-slate-200"
                  value={newTask.topic}
                  onChange={(e) => setNewTask({ ...newTask, topic: e.target.value })}
                  placeholder="e.g. Definite Integrals"
                />
              </div>
              <div className="flex gap-3 pt-4">
                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-2.5 bg-slate-100 dark:bg-white/5 hover:bg-slate-200 dark:hover:bg-white/10 text-slate-700 dark:text-white rounded-lg transition-colors font-bold uppercase tracking-wider text-sm">
                  Cancel
                </button>
                <button type="submit" className="flex-1 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition-colors font-bold uppercase tracking-wider text-sm">
                  Assign
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

    </div>
  );
};

export default MonthPlanner;

import React, { useState, useEffect } from 'react';
import { Menu, Plus, BookOpen, Calendar, TrendingUp, Smile, ChevronLeft, ChevronRight, Edit2, Trash2, Lightbulb } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/authContext';
import { logout } from '../firebase/authService';
import { getReflections, createReflection as createReflectionApi, deleteReflection as deleteReflectionApi } from '../services/api';

const MOODS = [
  { emoji: '≡ƒÿè', label: 'Great', color: 'text-emerald-500 dark:text-emerald-400' },
  { emoji: '≡ƒÖé', label: 'Good', color: 'text-blue-500 dark:text-blue-400' },
  { emoji: '≡ƒÿÉ', label: 'Okay', color: 'text-yellow-500 dark:text-yellow-400' },
  { emoji: '≡ƒÿò', label: 'Difficult', color: 'text-orange-500 dark:text-orange-400' },
  { emoji: '≡ƒÿ₧', label: 'Struggling', color: 'text-red-500 dark:text-red-400' },
];

const ReflectionPage = () => {
  const navigate = useNavigate();
  const { dbUser } = useAuth();
  const [entries, setEntries] = useState([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedEntry, setSelectedEntry] = useState(null);
  const [currentMonth, setCurrentMonth] = useState(new Date());

  // Fetch reflections from backend
  useEffect(() => {
    if (!dbUser?.id) return;
    const fetchReflections = async () => {
      try {
        const res = await getReflections(dbUser.id);
        const fetchedEntries = Array.isArray(res.data) ? res.data : [];
        setEntries(fetchedEntries);
      } catch (error) {
        console.error('Error fetching reflections:', error);
      }
    };
    fetchReflections();
  }, [dbUser?.id]);

  const handleLogout = async () => {
    try {
      await logout();
      navigate('/login', { replace: true });
    } catch (err) {
      console.error(err.message);
    }
  };

  const addEntry = async (e) => {
    e.preventDefault();
    if (!dbUser?.id) return;
    const formData = new FormData(e.target);

    const newEntry = {
      date: new Date().toISOString().split('T')[0],
      mood: formData.get('mood'),
      studyHours: parseFloat(formData.get('studyHours')),
      energyLevel: parseInt(formData.get('energyLevel')),
      wentWell: formData.get('wentWell'),
      toImprove: formData.get('toImprove'),
      tomorrowPlan: formData.get('tomorrowPlan'),
    };

    try {
      const res = await createReflectionApi(dbUser.id, newEntry);
      setEntries(prev => [res.data, ...prev]);
    } catch (error) {
      console.error('Error creating reflection:', error);
    }

    setShowAddModal(false);
    e.target.reset();
  };

  const deleteEntry = async (id) => {
    if(confirm('Are you sure you want to delete this reflection?')) {
      try {
        await deleteReflectionApi(id);
        setEntries(prev => prev.filter(e => e.id !== id));
      } catch (error) {
        console.error('Error deleting reflection:', error);
      }
      setSelectedEntry(null);
    }
  };

  const today = new Date().toISOString().split('T')[0];
  const hasEntryToday = entries.some(e => e.date === today);

  // Calculate streak
  const sortedDates = entries.map(e => e.date).sort().reverse();
  let streak = 0;
  let checkDate = new Date();

  for (let date of sortedDates) {
    const entryDate = new Date(date);
    const daysDiff = Math.floor((checkDate - entryDate) / (1000 * 60 * 60 * 24));

    if (daysDiff === streak) {
      streak++;
    } else {
      break;
    }
  }

  // Calendar data
  const getEntriesForMonth = (month) => {
    const year = month.getFullYear();
    const monthNum = month.getMonth();
    return entries.filter(e => {
      const entryDate = new Date(e.date);
      return entryDate.getFullYear() === year && entryDate.getMonth() === monthNum;
    });
  };

  const monthEntries = getEntriesForMonth(currentMonth);

  return (
    <div className="space-y-6">
      <div className="max-w-[1400px] mx-auto">

        {/* Header Options */}
        <div className="flex justify-between items-center mb-6">
          <div className="flex items-center gap-2">
             <h2 className="text-2xl font-black text-slate-800 dark:text-white uppercase tracking-wider flex items-center gap-2">
                <BookOpen size={24} className="text-purple-500" /> Daily Reflection
              </h2>
          </div>
          <div className="flex items-center gap-3">
             {!hasEntryToday && (
              <button onClick={() => setShowAddModal(true)} className="px-5 py-2.5 rounded-xl bg-purple-600 hover:bg-purple-700 text-white font-bold transition-all duration-200 flex items-center gap-2 shadow-lg shadow-purple-500/30 uppercase tracking-wider text-sm">
                <Plus size={18} /> Today's Entry
              </button>
            )}
          </div>
        </div>

        {/* Tips */}
        <div className="mb-6 bg-gradient-to-r from-purple-50 to-pink-50 dark:from-purple-500/10 dark:to-pink-500/10 border border-purple-100 dark:border-purple-500/20 rounded-2xl p-5 shadow-sm">
          <div className="flex items-start gap-4">
            <Lightbulb size={24} className="text-purple-600 dark:text-purple-400 shrink-0 mt-0.5" />
            <div>
              <h3 className="text-sm font-black text-purple-700 dark:text-purple-400 uppercase tracking-wider mb-2">Power of Reflection</h3>
              <ul className="text-xs font-medium text-slate-600 dark:text-slate-400 space-y-1.5 leading-relaxed">
                <li>ΓÇó Daily reflection improves learning by 20-30% (research-backed).</li>
                <li>ΓÇó Identify patterns: What study methods work best for you?</li>
                <li>ΓÇó Track emotional state: Energy levels affect performance.</li>
                <li>ΓÇó Plan ahead: Write tomorrow's priorities before sleeping.</li>
              </ul>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">

          {/* Left: Stats & Calendar */}
          <div className="space-y-6">

            {/* Streak */}
            <div className="bg-gradient-to-br from-orange-50 to-red-50 dark:from-orange-900/20 dark:to-red-900/20 border border-orange-100 dark:border-orange-500/20 rounded-2xl p-6 shadow-sm">
              <div className="flex items-center gap-4 mb-3">
                <div className="w-14 h-14 rounded-2xl bg-gradient-to-br from-orange-400 to-red-500 flex items-center justify-center shadow-lg shadow-red-500/20">
                  <TrendingUp size={24} className="text-white" />
                </div>
                <div>
                  <div className="text-4xl font-black text-slate-900 dark:text-white leading-none">{streak}</div>
                  <div className="text-xs font-bold text-slate-500 uppercase tracking-widest mt-1">Day Streak ≡ƒöÑ</div>
                </div>
              </div>
              {streak >= 7 && (
                <p className="text-[11px] font-bold text-orange-600 dark:text-orange-400 uppercase tracking-wider mt-3">Amazing! Keep the momentum going!</p>
              )}
            </div>

            {/* Calendar Heatmap */}
            <div className="bg-white dark:bg-[#0a0f1e]/60 border border-slate-200 dark:border-white/[0.06] rounded-2xl p-6 shadow-sm">
              <div className="flex items-center justify-between mb-6">
                <button onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1))} className="p-1.5 text-slate-400 hover:text-slate-800 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-white/10 rounded-lg transition-colors">
                  <ChevronLeft size={18} />
                </button>
                <h3 className="text-sm font-black uppercase tracking-wider text-slate-800 dark:text-white">
                  {currentMonth.toLocaleString('default', { month: 'long', year: 'numeric' })}
                </h3>
                <button onClick={() => setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1))} className="p-1.5 text-slate-400 hover:text-slate-800 dark:hover:text-white hover:bg-slate-100 dark:hover:bg-white/10 rounded-lg transition-colors">
                  <ChevronRight size={18} />
                </button>
              </div>

              <div className="grid grid-cols-7 gap-1.5">
                {['S', 'M', 'T', 'W', 'T', 'F', 'S'].map((d, i) => (
                  <div key={i} className="text-[10px] text-slate-400 text-center font-bold uppercase">{d}</div>
                ))}

                {Array.from({ length: 35 }, (_, i) => {
                  const firstDay = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();
                  const day = i - firstDay + 1;
                  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();

                  if (day < 1 || day > daysInMonth) {
                    return <div key={i} className="aspect-square" />;
                  }

                  const dateStr = `${currentMonth.getFullYear()}-${String(currentMonth.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
                  const hasEntry = entries.some(e => e.date === dateStr);

                  return (
                    <div 
                      key={i}
                      className={`aspect-square rounded flex items-center justify-center text-[10px] font-bold transition-all shadow-sm ${
                        hasEntry 
                          ? 'bg-purple-500 text-white shadow-purple-500/20' 
                          : 'bg-slate-50 dark:bg-white/[0.03] text-slate-500 hover:bg-slate-100 dark:hover:bg-white/[0.08] border border-slate-100 dark:border-transparent'
                      }`}
                    >
                      {day}
                    </div>
                  );
                })}
              </div>

              <div className="mt-5 flex items-center gap-2 text-[10px] font-bold uppercase tracking-wider text-slate-500">
                <div className="w-3 h-3 rounded bg-purple-500 shadow-sm" />
                <span>Has entry</span>
              </div>
            </div>

            {/* Stats */}
            <div className="bg-white dark:bg-[#0a0f1e]/60 border border-slate-200 dark:border-white/[0.06] rounded-2xl p-6 shadow-sm">
              <h3 className="text-sm font-black text-slate-800 dark:text-white uppercase tracking-wider mb-5">This Month</h3>
              <div className="space-y-4">
                <div className="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-white/5">
                  <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Entries</span>
                  <span className="text-base font-black text-slate-800 dark:text-white">{monthEntries.length}</span>
                </div>
                <div className="flex items-center justify-between pb-3 border-b border-slate-100 dark:border-white/5">
                  <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Avg Study Hours</span>
                  <span className="text-base font-black text-blue-600 dark:text-blue-400">
                    {monthEntries.length > 0 ? (monthEntries.reduce((sum, e) => sum + e.studyHours, 0) / monthEntries.length).toFixed(1) : 0}h
                  </span>
                </div>
                <div className="flex items-center justify-between">
                  <span className="text-xs font-bold text-slate-500 uppercase tracking-widest">Avg Energy</span>
                  <span className="text-base font-black text-emerald-600 dark:text-emerald-400">
                    {monthEntries.length > 0 ? (monthEntries.reduce((sum, e) => sum + e.energyLevel, 0) / monthEntries.length).toFixed(1) : 0}/5
                  </span>
                </div>
              </div>
            </div>
          </div>

          {/* Right: Entries Timeline */}
          <div className="lg:col-span-2">

            <div className="space-y-5">
