                      <div className="text-[10px] font-black uppercase tracking-widest text-emerald-600 dark:text-emerald-400 mb-2 flex items-center gap-2">Γ£ô What went well</div>
                      <p className="text-sm font-medium text-slate-700 dark:text-slate-300 leading-relaxed">{entry.wentWell}</p>
