              ))}

              {entries.length === 0 && (
                <div className="text-center py-20 bg-slate-50 dark:bg-white/[0.02] border border-slate-200 dark:border-white/[0.05] border-dashed rounded-2xl flex flex-col items-center justify-center">
                  <div className="w-20 h-20 bg-slate-200 dark:bg-white/5 rounded-full flex items-center justify-center mb-6">
                     <BookOpen size={32} className="text-slate-400" />
                  </div>
                  <h3 className="text-lg font-black text-slate-800 dark:text-white uppercase tracking-wider mb-2">No reflections yet</h3>
                  <p className="text-sm font-medium text-slate-500 mb-6">Take a moment to reflect on your day and plan for tomorrow.</p>
                  <button onClick={() => setShowAddModal(true)} className="px-6 py-2.5 bg-purple-500 hover:bg-purple-600 text-white text-sm font-bold uppercase tracking-wider rounded-xl transition-colors shadow-lg shadow-purple-500/20">Write your first entry</button>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Add Entry Modal */}
      {showAddModal && (
        <div className="fixed inset-0 bg-slate-900/60 dark:bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4" onClick={() => setShowAddModal(false)}>
          <div className="bg-white dark:bg-[#111827] border border-slate-200 dark:border-white/10 rounded-3xl p-6 md:p-8 max-w-2xl w-full max-h-[90vh] overflow-y-auto shadow-2xl custom-scrollbar" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-black text-slate-900 dark:text-white mb-6 uppercase tracking-wider border-b border-slate-100 dark:border-white/10 pb-4">Today's Reflection</h3>
            <form onSubmit={addEntry} className="space-y-6">

              {/* Mood */}
              <div>
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-3 block">How was your day?</label>
                <div className="flex gap-2">
                  {MOODS.map((mood, idx) => (
                    <label key={idx} className="flex-1 cursor-pointer group">
                      <input type="radio" name="mood" value={mood.emoji} defaultChecked={idx===2} required className="sr-only peer" />
                      <div className="p-3 md:p-4 rounded-2xl bg-slate-50 dark:bg-white/[0.02] border border-slate-200 dark:border-white/[0.05] group-hover:bg-slate-100 dark:group-hover:bg-white/[0.05] peer-checked:bg-purple-50 peer-checked:dark:bg-purple-500/10 peer-checked:border-purple-500 peer-checked:shadow-md peer-checked:shadow-purple-500/10 transition-all text-center">
                        <div className="text-2xl md:text-3xl mb-2 grayscale group-hover:grayscale-0 peer-checked:grayscale-0 transition-all transform peer-checked:scale-110">{mood.emoji}</div>
                        <div className="text-[10px] font-bold text-slate-500 uppercase tracking-wider">{mood.label}</div>
                      </div>
                    </label>
                  ))}
                </div>
              </div>

              {/* Study Hours & Energy */}
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-2 block">Study Hours</label>
                  <input name="studyHours" type="number" step="0.5" placeholder="7.5" required className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/[0.02] border border-slate-200 dark:border-white/[0.05] text-slate-900 dark:text-white outline-none focus:border-purple-500 transition-colors font-medium text-sm" />
                </div>
                <div>
                  <label className="text-xs font-bold text-slate-500 uppercase tracking-widest mb-2 block">Energy (1-5)</label>
                  <input name="energyLevel" type="number" min="1" max="5" placeholder="4" required className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/[0.02] border border-slate-200 dark:border-white/[0.05] text-slate-900 dark:text-white outline-none focus:border-purple-500 transition-colors font-medium text-sm" />
                </div>
              </div>

              {/* Reflections */}
              <div className="space-y-4 pt-2">
                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-emerald-600 dark:text-emerald-400 mb-2 flex items-center gap-2">Γ£ô What went well today?</label>
                  <textarea name="wentWell" rows="2" placeholder="e.g., Completed DP module..." required className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/[0.02] border border-slate-200 dark:border-emerald-500/20 text-slate-900 dark:text-white placeholder-slate-400 focus:border-emerald-500 transition-colors outline-none resize-none text-sm font-medium" />
                </div>

                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-orange-600 dark:text-orange-400 mb-2 flex items-center gap-2">Γû│ What could be improved?</label>
                  <textarea name="toImprove" rows="2" placeholder="e.g., Got distracted during afternoon..." required className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/[0.02] border border-slate-200 dark:border-orange-500/20 text-slate-900 dark:text-white placeholder-slate-400 focus:border-orange-500 transition-colors outline-none resize-none text-sm font-medium" />
                </div>

                <div>
                  <label className="text-[10px] font-black uppercase tracking-widest text-blue-600 dark:text-blue-400 mb-2 flex items-center gap-2">ΓåÆ Tomorrow's plan</label>
                  <textarea name="tomorrowPlan" rows="2" placeholder="e.g., Start Greedy algorithms..." required className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/[0.02] border border-slate-200 dark:border-blue-500/20 text-slate-900 dark:text-white placeholder-slate-400 focus:border-blue-500 transition-colors outline-none resize-none text-sm font-medium" />
                </div>
              </div>

              <div className="flex gap-4 pt-4 border-t border-slate-100 dark:border-white/10 mt-6">
                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-3.5 rounded-xl bg-slate-100 dark:bg-white/5 text-slate-700 dark:text-white font-bold uppercase tracking-wider text-sm hover:bg-slate-200 dark:hover:bg-white/10 transition-colors">Cancel</button>
                <button type="submit" className="flex-1 py-3.5 rounded-xl bg-purple-600 text-white font-bold uppercase tracking-wider text-sm hover:bg-purple-700 transition-colors shadow-lg shadow-purple-500/20">Save Entry</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default ReflectionPage;

import React, { useState, useEffect } from 'react';
import { User, BookOpen, Clock, Palette, Bell, Shield, Info, Upload, Download, Trash2, Sun, Moon, Monitor } from 'lucide-react';
import { useTheme } from '../context/ThemeContext';
import { useAuth } from '../context/authContext';
import { getExams, getUserByFirebaseUid, updateUserProfile } from '../services/api';

const SettingsPage = () => {
  const { theme, toggleTheme } = useTheme();
  const { user, dbUser, refreshUser } = useAuth();

  // Personal Information
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [photoUrl, setPhotoUrl] = useState('');

  // Exam Details
  const [examOptions, setExamOptions] = useState([]);
  const [selectedExam, setSelectedExam] = useState('');
  const [examDate, setExamDate] = useState('');
  const [targetRank, setTargetRank] = useState('');

  // Preferences
  const [pomodoroTime, setPomodoroTime] = useState('25');
  const [weekStart, setWeekStart] = useState('Monday');
  const [timeFormat, setTimeFormat] = useState('12h');

  // Appearance
  const [themeMode, setThemeMode] = useState(theme);

  // Notifications
  const [browserNotifs, setBrowserNotifs] = useState(true);
  const [timerSound, setTimerSound] = useState(true);
  const [breakReminders, setBreakReminders] = useState(true);

  const [saving, setSaving] = useState(false);
  const [saveMsg, setSaveMsg] = useState('');

  // Load user profile and exam options from backend
  useEffect(() => {
    const loadData = async () => {
      try {
        // Fetch exam options
        const examsRes = await getExams();
        if (Array.isArray(examsRes.data)) {
          setExamOptions(examsRes.data.map(e => e.name || e));
        }
      } catch (error) {
        console.error('Error fetching exams:', error);
      }
    };
    loadData();
  }, []);

  // Populate form with dbUser data
  useEffect(() => {
    if (dbUser) {
      setFullName(dbUser.fullName || '');
      setEmail(dbUser.email || user?.email || '');
      setPhotoUrl(dbUser.photoUrl || '');
      setSelectedExam(dbUser.exam || '');
      setExamDate(dbUser.examDate || '');
      setTargetRank(dbUser.targetRank || '');
      setPomodoroTime(dbUser.pomodoroTime || '25');
      setWeekStart(dbUser.weekStart || 'Monday');
      setTimeFormat(dbUser.timeFormat || '12h');
      setBrowserNotifs(dbUser.browserNotifs !== false);
      setTimerSound(dbUser.timerSound !== false);
      setBreakReminders(dbUser.breakReminders !== false);
      if (dbUser.theme) setThemeMode(dbUser.theme);
    }
  }, [dbUser]);

  const handleThemeChange = (mode) => {
    setThemeMode(mode);
    if (mode === 'auto') {
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      if ((prefersDark && theme !== 'dark') || (!prefersDark && theme !== 'light')) {
        toggleTheme();
      }
    } else if (mode !== theme) {
      toggleTheme();
    }
  };

  const handleSave = async () => {
    if (!dbUser?.id) return;
    setSaving(true);
    setSaveMsg('');
    try {
      await updateUserProfile(dbUser.id, {
        fullName,
        photoUrl,
        exam: selectedExam,
        examDate: examDate || null,
        targetRank,
        pomodoroTime,
        weekStart,
        timeFormat,
        theme: themeMode,
        browserNotifs,
        timerSound,
        breakReminders,
      });
      if (refreshUser) await refreshUser();
      setSaveMsg('Settings saved successfully!');
      setTimeout(() => setSaveMsg(''), 3000);
    } catch (error) {
      console.error('Error saving settings:', error);
      setSaveMsg('Error saving settings. Please try again.');
    } finally {
      setSaving(false);
    }
  };

  const handleExport = () => {
    const data = { fullName, selectedExam, examDate, targetRank, pomodoroTime, weekStart, timeFormat, themeMode, browserNotifs, timerSound, breakReminders };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = 'prepmate-settings.json';
    a.click();
    URL.revokeObjectURL(url);
  };

  const cardClass = "bg-white dark:bg-[#0a0f1e]/60 border border-slate-200 dark:border-white/[0.06] rounded-2xl p-6 shadow-sm dark:shadow-none";
  const inputClass = "w-full px-4 py-2.5 rounded-xl bg-white dark:bg-white/[0.05] border border-slate-300 dark:border-white/[0.1] text-slate-900 dark:text-slate-200 outline-none focus:border-blue-500/50 focus:ring-2 focus:ring-blue-500/20 transition-all text-sm";
  const labelClass = "text-xs text-slate-500 font-semibold block mb-1.5";
  const sectionTitleClass = "text-base font-bold text-slate-900 dark:text-white flex items-center gap-2 mb-4";

  return (
    <div className="space-y-6 max-w-3xl">

      {/* Save Button & Status */}
      <div className="flex items-center justify-between">
        <div>
          {saveMsg && <p className={`text-sm font-medium ${saveMsg.includes('Error') ? 'text-red-500' : 'text-emerald-500'}`}>{saveMsg}</p>}
        </div>
        <button 
          onClick={handleSave} 
          disabled={saving}
          className="px-6 py-2.5 bg-blue-600 hover:bg-blue-700 text-white rounded-xl text-sm font-bold uppercase tracking-wider transition-colors shadow-lg shadow-blue-500/20 disabled:opacity-50"
        >
          {saving ? 'Saving...' : 'Save Settings'}
        </button>
      </div>

      {/* 1. Personal Information */}
      <div className={cardClass}>
        <h3 className={sectionTitleClass}>
          <User size={18} className="text-blue-400" />
          Personal Information
        </h3>
        <div className="space-y-4">
          <div className="flex items-center gap-4 mb-4">
            <div className="w-16 h-16 rounded-full bg-gradient-to-br from-blue-500 to-violet-500 flex items-center justify-center text-white font-bold text-xl shrink-0">
              {fullName ? fullName.charAt(0).toUpperCase() : 'U'}
            </div>
            <div>
              <button className="px-4 py-2 rounded-lg bg-blue-500/10 border border-blue-500/30 text-blue-400 text-xs font-bold hover:bg-blue-500/20 transition-all flex items-center gap-2">
                <Upload size={14} /> Upload Photo
              </button>
              <p className="text-[10px] text-slate-500 mt-1">JPG, PNG. Max 2MB</p>
            </div>
          </div>
          <div>
            <label className={labelClass}>Full Name</label>
            <input type="text" value={fullName} onChange={(e) => setFullName(e.target.value)} placeholder="Enter your full name" className={inputClass} />
          </div>
          <div>
            <label className={labelClass}>Email</label>
            <input type="email" value={email} disabled className={`${inputClass} opacity-60 cursor-not-allowed`} />
            <p className="text-[10px] text-slate-500 mt-1">Email cannot be changed</p>
          </div>
        </div>
      </div>

      {/* 2. Exam Details */}
      <div className={cardClass}>
        <h3 className={sectionTitleClass}>
          <BookOpen size={18} className="text-emerald-400" />
          Exam Details
        </h3>
        <div className="space-y-4">
          <div>
            <label className={labelClass}>Target Exam</label>
            <select value={selectedExam} onChange={(e) => setSelectedExam(e.target.value)} className={inputClass}>
              <option value="">Select exam...</option>
              {examOptions.map(exam => (
                <option key={exam} value={exam}>{exam}</option>
              ))}
            </select>
          </div>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className={labelClass}>Exam Date</label>
              <input type="date" value={examDate} onChange={(e) => setExamDate(e.target.value)} className={inputClass} />
            </div>
            <div>
              <label className={labelClass}>Target Rank</label>
              <input type="number" value={targetRank} onChange={(e) => setTargetRank(e.target.value)} placeholder="e.g., 100" className={inputClass} />
            </div>
          </div>
        </div>
      </div>

      {/* 3. Preferences */}
      <div className={cardClass}>
        <h3 className={sectionTitleClass}>
          <Clock size={18} className="text-violet-400" />
          Preferences
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <label className={labelClass}>Default Pomodoro</label>
            <select value={pomodoroTime} onChange={(e) => setPomodoroTime(e.target.value)} className={inputClass}>
              <option value="25">25 minutes</option>
              <option value="50">50 minutes</option>
              <option value="30">30 minutes</option>
              <option value="45">45 minutes</option>
            </select>
          </div>
          <div>
            <label className={labelClass}>Week Starts On</label>
            <select value={weekStart} onChange={(e) => setWeekStart(e.target.value)} className={inputClass}>
              <option value="Monday">Monday</option>
              <option value="Sunday">Sunday</option>
              <option value="Saturday">Saturday</option>
            </select>
          </div>
          <div>
            <label className={labelClass}>Time Format</label>
            <select value={timeFormat} onChange={(e) => setTimeFormat(e.target.value)} className={inputClass}>
              <option value="12h">12-hour</option>
              <option value="24h">24-hour</option>
            </select>
          </div>
        </div>
      </div>

      {/* 4. Appearance */}
      <div className={cardClass}>
        <h3 className={sectionTitleClass}>
          <Palette size={18} className="text-pink-400" />
          Appearance
        </h3>
        <div className="grid grid-cols-3 gap-3">
          {[
            { value: 'light', label: 'Light', icon: Sun },
            { value: 'dark', label: 'Dark', icon: Moon },
            { value: 'auto', label: 'Auto', icon: Monitor },
          ].map(({ value, label, icon: Icon }) => (
            <button
              key={value}
              onClick={() => handleThemeChange(value)}
              className={`p-4 rounded-xl border text-center transition-all ${
                themeMode === value
                  ? 'bg-blue-500/10 border-blue-500/50 text-blue-400'
                  : 'bg-slate-50 dark:bg-white/[0.03] border-slate-200 dark:border-white/[0.06] text-slate-500 hover:bg-slate-100 dark:hover:bg-white/[0.05]'
              }`}
            >
              <Icon size={20} className="mx-auto mb-2" />
              <span className="text-sm font-semibold">{label}</span>
            </button>
          ))}
        </div>
      </div>

      {/* 5. Notifications */}
      <div className={cardClass}>
        <h3 className={sectionTitleClass}>
          <Bell size={18} className="text-yellow-400" />
          Notifications
        </h3>
        <div className="space-y-4">
          {[
            { label: 'Browser Notifications', description: 'Get notified about study reminders', value: browserNotifs, setter: setBrowserNotifs },
            { label: 'Timer Sound', description: 'Play sound when timer ends', value: timerSound, setter: setTimerSound },
            { label: 'Break Reminders', description: 'Remind to take breaks during study', value: breakReminders, setter: setBreakReminders },
          ].map(({ label, description, value, setter }) => (
            <div key={label} className="flex items-center justify-between p-3 rounded-xl bg-slate-50 dark:bg-white/[0.02] border border-slate-100 dark:border-white/[0.04]">
              <div>
                <div className="text-sm font-semibold text-slate-900 dark:text-white">{label}</div>
                <div className="text-xs text-slate-500">{description}</div>
              </div>
              <button
                onClick={() => setter(!value)}
                className={`w-11 h-6 rounded-full transition-all relative ${
                  value ? 'bg-blue-500' : 'bg-slate-300 dark:bg-slate-600'
                }`}
              >
                <div className={`w-4.5 h-4.5 absolute top-[3px] rounded-full bg-white shadow transition-all ${
                  value ? 'left-[22px]' : 'left-[3px]'
                }`} style={{ width: '18px', height: '18px' }} />
              </button>
            </div>
          ))}
        </div>
      </div>

      {/* 6. Data & Privacy */}
      <div className={cardClass}>
        <h3 className={sectionTitleClass}>
          <Shield size={18} className="text-orange-400" />
          Data & Privacy
        </h3>
        <div className="space-y-3">
          <button onClick={handleExport} className="w-full flex items-center justify-between p-4 rounded-xl bg-slate-50 dark:bg-white/[0.02] border border-slate-200 dark:border-white/[0.06] hover:bg-slate-100 dark:hover:bg-white/[0.04] transition-colors text-left group">
            <div className="flex items-center gap-3">
              <Download size={18} className="text-blue-400" />
              <div>
                <div className="text-sm font-semibold text-slate-900 dark:text-white">Export Data</div>
                <div className="text-xs text-slate-500">Download all your data as JSON</div>
              </div>
            </div>
            <span className="text-xs text-blue-400 font-bold opacity-0 group-hover:opacity-100 transition-opacity">Export ΓåÆ</span>
          </button>

          <button onClick={() => { localStorage.clear(); alert('Cache cleared!'); }} className="w-full flex items-center justify-between p-4 rounded-xl bg-slate-50 dark:bg-white/[0.02] border border-slate-200 dark:border-white/[0.06] hover:bg-slate-100 dark:hover:bg-white/[0.04] transition-colors text-left group">
            <div className="flex items-center gap-3">
              <Trash2 size={18} className="text-yellow-400" />
              <div>
                <div className="text-sm font-semibold text-slate-900 dark:text-white">Clear Cache</div>
                <div className="text-xs text-slate-500">Remove locally stored data</div>
              </div>
            </div>
            <span className="text-xs text-yellow-400 font-bold opacity-0 group-hover:opacity-100 transition-opacity">Clear ΓåÆ</span>
          </button>

          <button onClick={() => { if (window.confirm('Are you sure? This cannot be undone.')) console.log('Account deletion requested'); }} className="w-full flex items-center justify-between p-4 rounded-xl bg-red-500/5 border border-red-500/20 hover:bg-red-500/10 transition-colors text-left group">
            <div className="flex items-center gap-3">
              <Trash2 size={18} className="text-red-400" />
              <div>
                <div className="text-sm font-semibold text-red-400">Delete Account</div>
                <div className="text-xs text-slate-500">Permanently delete your account and data</div>
