  const [questionLaps, setQuestionLaps] = useState([]);
  const [sessionName, setSessionName] = useState("Question Solving Session");
  const [isEditingSessionName, setIsEditingSessionName] = useState(false);
  const [editingSessionId, setEditingSessionId] = useState(null);
  const [editSessionValue, setEditSessionValue] = useState("");
  const [sessions, setSessions] = useState([]);
  const [currentSubject, setCurrentSubject] = useState('');
  const [showSessionModal, setShowSessionModal] = useState(false);

  // Fetch timer sessions from backend
  useEffect(() => {
    if (!dbUser?.id) return;
    const fetchSessions = async () => {
      try {
        const res = await getTimerSessions(dbUser.id);
        const fetchedSessions = Array.isArray(res.data) ? res.data : [];
        // Map backend Date to local time formats if necessary or use as-is
        const processedSessions = fetchedSessions.map(s => ({
          ...s,
          time: s.time || new Date(s.createdAt || Date.now()).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }));
        setSessions(processedSessions);
      } catch (error) {
        console.error('Error fetching timer sessions:', error);
      }
    };
    fetchSessions();
  }, [dbUser?.id]);

  useEffect(() => {
    let interval;
    if (pomodoroRunning && pomodoroTime > 0) {
      interval = setInterval(() => {
        setPomodoroTime(t => {
          if (t <= 1) {
            setPomodoroRunning(false);
            logSession('Pomodoro', Math.floor((25 * 60 - t) / 60));
            return 0;
          }
          return t - 1;
        });
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [pomodoroRunning, pomodoroTime]);

  useEffect(() => {
    let interval;
    if (trackerRunning) {
      interval = setInterval(() => {
        setSessionTime(t => t + 1);
        setQuestionTime(t => t + 1);
      }, 1000);
    }
    return () => clearInterval(interval);
  }, [trackerRunning]);

  const handleNextQuestion = () => {
    if (questionTime === 0 && sessionTime === 0) return;
    setQuestionLaps(prev => [...prev, questionTime]);
    setQuestionsSolved(s => s + 1);
    setQuestionTime(0);
  };

  const handleEndSession = () => {
    if (sessionTime === 0) return;
    const avgSeconds = questionsSolved > 0 ? Math.floor(sessionTime / questionsSolved) : 0;
    const avgFormatted = formatTime(avgSeconds);
    logSession(`${sessionName} (${questionsSolved} Qs, Avg: ${avgFormatted})`, Math.floor(sessionTime / 60));
    setTrackerRunning(false);
    setSessionTime(0);
    setQuestionTime(0);
    setQuestionsSolved(0);
    setQuestionLaps([]);
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  const startEditingSessionLog = (session) => {
    setEditingSessionId(session.id);
    setEditSessionValue(session.type);
  };

  const saveSessionLogName = (id) => {
    setSessions(sessions.map(s => s.id === id ? { ...s, type: editSessionValue } : s));
    setEditingSessionId(null);
  };

  const logSession = async (type, duration) => {
    if (!dbUser?.id) return;
    const now = new Date();

    const newSession = {
      type,
      duration,
      completed: true,
      subject: currentSubject || null,
      time: now.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' }),
    };

    try {
      const res = await createTimerSessionApi(dbUser.id, newSession);
      setSessions(prev => [{
        ...res.data,
        time: res.data.time || newSession.time
      }, ...prev]);
    } catch (error) {
      console.error('Error creating timer session:', error);
    }
  };

  const resetPomodoro = (minutes = 25) => {
    setPomodoroTime(minutes * 60);
    setPomodoroRunning(false);
  };

  const totalStudyTime = sessions
    .filter(s => s.type === 'Pomodoro')
    .reduce((sum, s) => sum + s.duration, 0);

  const todaySessions = sessions.filter(s => s.type === 'Pomodoro').length;

  return (
    <div className="space-y-6">

      {/* Tips Section */}
      <div className="bg-gradient-to-r from-blue-500/10 to-violet-500/10 border border-blue-500/20 rounded-xl p-5">
        <div className="flex items-start gap-3">
          <div className="w-10 h-10 rounded-lg bg-blue-500/20 flex items-center justify-center shrink-0">
            <Lightbulb size={18} className="text-blue-400" />
          </div>
          <div>
            <h3 className="text-sm font-bold text-white mb-2">ΓÅ▒∩╕Å Pomodoro Technique Tips</h3>
            <ul className="text-xs text-slate-300 space-y-1">
              <li>ΓÇó Work in focused 25-minute blocks followed by 5-minute breaks</li>
              <li>ΓÇó After 4 pomodoros, take a longer 15-30 minute break</li>
              <li>ΓÇó Remove all distractions during pomodoro sessions</li>
              <li>ΓÇó Use stopwatch for tasks that need continuous focus without breaks</li>
            </ul>
          </div>
        </div>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <div className="bg-[#0a0f1e]/60 border border-white/[0.06] rounded-xl p-5">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-xl bg-blue-500/10 border border-blue-500/30 flex items-center justify-center">
              <Clock size={20} className="text-blue-400" />
            </div>
            <div>
              <div className="text-2xl font-black text-white">{totalStudyTime}m</div>
              <div className="text-xs text-slate-500 font-medium">Today's Study Time</div>
            </div>
          </div>
        </div>

        <div className="bg-[#0a0f1e]/60 border border-white/[0.06] rounded-xl p-5">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-xl bg-emerald-500/10 border border-emerald-500/30 flex items-center justify-center">
              <Zap size={20} className="text-emerald-400" />
            </div>
            <div>
              <div className="text-2xl font-black text-white">{todaySessions}</div>
              <div className="text-xs text-slate-500 font-medium">Pomodoros Done</div>
            </div>
          </div>
        </div>

        <div className="bg-[#0a0f1e]/60 border border-white/[0.06] rounded-xl p-5">
          <div className="flex items-center gap-3">
            <div className="w-12 h-12 rounded-xl bg-violet-500/10 border border-violet-500/30 flex items-center justify-center">
              <TrendingUp size={20} className="text-violet-400" />
            </div>
            <div>
              <div className="text-2xl font-black text-white">{sessions.length}</div>
              <div className="text-xs text-slate-500 font-medium">Total Sessions</div>
            </div>
          </div>
        </div>
      </div>

      {/* Timers Grid */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">

        {/* Pomodoro Timer */}
        <div className="bg-[#0a0f1e]/60 border border-white/[0.06] rounded-2xl p-8 text-center">
          <div className="flex items-center justify-center gap-2 mb-6">
            <Clock size={20} className="text-blue-400" />
            <h2 className="text-sm font-bold text-white uppercase tracking-wider">Pomodoro Timer</h2>
          </div>

          <div className="text-7xl font-black text-white mb-8 font-mono tracking-tight">
            {formatTime(pomodoroTime)}
          </div>

          <div className="flex items-center justify-center gap-3 mb-6">
            <button
              onClick={() => setPomodoroRunning(!pomodoroRunning)}
              disabled={pomodoroTime === 0}
              className="p-5 bg-blue-500 hover:bg-blue-600 disabled:bg-slate-700 disabled:cursor-not-allowed rounded-full transition-all shadow-lg shadow-blue-500/30"
            >
              {pomodoroRunning ? 
                <Pause size={28} className="text-white" /> : 
                <Play size={28} className="text-white" />
              }
            </button>
            <button
              onClick={() => resetPomodoro()}
              className="p-5 bg-white/5 hover:bg-white/10 rounded-full transition-all"
            >
              <RotateCcw size={28} className="text-slate-400" />
            </button>
          </div>

          <div className="flex items-center justify-center gap-2">
            {[25, 15, 5].map(mins => (
              <button
                key={mins}
                onClick={() => resetPomodoro(mins)}
                className="px-4 py-2 bg-white/5 hover:bg-white/10 text-slate-300 text-sm font-semibold rounded-lg transition-all"
              >
                {mins}m
              </button>
            ))}
          </div>
        </div>

        {/* Question Tracker */}
        <div className="bg-[#0a0f1e]/60 border border-white/[0.06] rounded-2xl p-8 text-center flex flex-col items-center">
          <div className="flex flex-col items-center justify-center gap-2 mb-6 w-full">
            <div className="flex items-center gap-2">
              <Clock size={20} className="text-emerald-400" />
              <h2 className="text-sm font-bold text-white uppercase tracking-wider">Question Tracker</h2>
            </div>

            {isEditingSessionName ? (
              <input 
                type="text" 
                value={sessionName}
                onChange={(e) => setSessionName(e.target.value)}
                onBlur={() => setIsEditingSessionName(false)}
                onKeyDown={(e) => e.key === 'Enter' && setIsEditingSessionName(false)}
                className="bg-white/5 border border-white/10 rounded-lg px-3 py-1.5 text-white text-center text-sm outline-none focus:border-emerald-500 transition-colors w-full max-w-xs mt-2"
                autoFocus
              />
            ) : (
              <div 
                className="flex items-center gap-2 cursor-pointer group hover:text-emerald-400 transition-colors mt-2"
                onClick={() => setIsEditingSessionName(true)}
              >
                <span className="text-white font-bold text-lg">{sessionName}</span>
                <Edit2 size={14} className="text-slate-500 group-hover:text-emerald-400" />
              </div>
            )}
          </div>

          <div className="w-full flex justify-between items-center mb-6 px-4">
             <div className="text-left w-[80px]">
               <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-1">Time</div>
               <div className="text-xl md:text-2xl font-mono font-bold text-white">{formatTime(sessionTime)}</div>
             </div>
             <div className="text-center w-[80px]">
               <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-1">Avg/Q</div>
               <div className="text-xl md:text-2xl font-mono font-bold text-blue-400">
                 {questionsSolved > 0 ? formatTime(Math.floor(sessionTime / questionsSolved)) : '00:00'}
               </div>
             </div>
             <div className="text-right w-[80px]">
               <div className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mb-1">Solved</div>
               <div className="text-xl md:text-2xl font-black text-emerald-400">{questionsSolved}</div>
             </div>
          </div>

          <div className="text-7xl font-black text-emerald-400 mb-8 font-mono tracking-tight transition-all">
            {formatTime(questionTime)}
          </div>

          <div className="flex w-full items-center justify-center gap-3 mb-6">
            <button
              onClick={() => setTrackerRunning(!trackerRunning)}
              className="w-16 h-16 flex items-center justify-center bg-emerald-500 hover:bg-emerald-600 rounded-full transition-all shadow-lg shadow-emerald-500/30"
            >
              {trackerRunning ? 
                <Pause size={28} className="text-white" /> : 
                <Play size={28} className="text-white ml-1" />
              }
            </button>
            <button
              onClick={handleNextQuestion}
              disabled={!trackerRunning}
              className="flex-1 max-w-[140px] h-16 bg-white/5 hover:bg-white/10 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold rounded-2xl flex items-center justify-center transition-all uppercase tracking-wider text-sm border border-white/5"
            >
              Next Q
            </button>
          </div>

          {(sessionTime > 0) && (
            <button
              onClick={handleEndSession}
              className="w-full mt-auto px-6 py-3.5 bg-rose-500/10 border border-rose-500/20 text-rose-400 hover:text-rose-300 text-sm font-bold uppercase tracking-wider rounded-xl hover:bg-rose-500/20 transition-all shadow-sm"
            >
              End Session & Log
            </button>
          )}
        </div>
      </div>

      {/* Sessions Log */}
      <div className="bg-[#0a0f1e]/60 border border-white/[0.06] rounded-2xl p-6">
        <h3 className="text-sm font-bold text-white mb-4">Today's Sessions</h3>

        {sessions.length === 0 ? (
          <div className="text-center py-12">
            <Clock size={48} className="mx-auto text-slate-700 mb-3" />
            <p className="text-slate-500 text-sm">No sessions yet today</p>
          </div>
        ) : (
          <div className="space-y-2">
            {sessions.map((session) => (
              <div 
                key={session.id} 
                className={`flex items-center justify-between p-4 rounded-lg border transition-all ${
                  session.type === 'Pomodoro' 
                    ? 'bg-blue-500/5 border-blue-500/20' 
                    : 'bg-emerald-500/5 border-emerald-500/20'
                }`}
              >
                <div className="flex items-center gap-3">
                  <div className={`w-2 h-2 rounded-full ${
                    session.type === 'Pomodoro' ? 'bg-blue-500' : 'bg-emerald-500'
                  }`} />
                  <div className="flex-1">
                    {editingSessionId === session.id ? (
                      <input
                        type="text"
                        value={editSessionValue}
                        onChange={(e) => setEditSessionValue(e.target.value)}
                        onBlur={() => saveSessionLogName(session.id)}
                        onKeyDown={(e) => { if (e.key === 'Enter') saveSessionLogName(session.id); }}
                        className="bg-white/5 border border-white/10 rounded-lg px-2 text-white text-sm outline-none focus:border-emerald-500 transition-colors w-full"
                        autoFocus
                      />
                    ) : (
                      <div 
                        className="flex items-center gap-2 cursor-pointer group hover:text-emerald-400 transition-colors"
                        onClick={() => startEditingSessionLog(session)}
                      >
                        <span className={`text-sm font-semibold ${session.type.startsWith('Pomodoro') ? 'text-blue-400' : 'text-emerald-400'}`}>
                          {session.type}
                        </span>
                        <Edit2 size={12} className="text-slate-500 opacity-0 group-hover:opacity-100 transition-opacity" />
                      </div>
                    )}
                    {session.subject && (
                      <span className="text-xs text-slate-500 mt-1 block">{session.subject}</span>
                    )}
                  </div>
                </div>
                <div className="flex items-center gap-4 text-xs text-slate-500">
                  <span>{session.duration} min</span>
                  <span>{session.time}</span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default TimersPage;

import React, { useState, useEffect } from 'react';
import { ChevronLeft, ChevronRight, Plus, Calendar as CalendarIcon, ArrowRight, Clock, X } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/authContext';
import { getWeeklyPlan, createWeeklyPlan as createWeeklyPlanApi, deleteWeeklyPlan as deleteWeeklyPlanApi, getSubjects } from '../services/api';

const DEFAULT_SUBJECT_COLORS = {
  'Algorithms': { bg: 'bg-blue-500/10', border: 'border-blue-500/30', text: 'text-blue-400', accent: 'bg-blue-500' },
  'Operating Systems': { bg: 'bg-violet-500/10', border: 'border-violet-500/30', text: 'text-violet-400', accent: 'bg-violet-500' },
  'DBMS': { bg: 'bg-cyan-500/10', border: 'border-cyan-500/30', text: 'text-cyan-400', accent: 'bg-cyan-500' },
  'Computer Networks': { bg: 'bg-orange-500/10', border: 'border-orange-500/30', text: 'text-orange-400', accent: 'bg-orange-500' },
  'General Aptitude': { bg: 'bg-yellow-500/10', border: 'border-yellow-500/30', text: 'text-yellow-400', accent: 'bg-yellow-500' },
  'Revision': { bg: 'bg-emerald-500/10', border: 'border-emerald-500/30', text: 'text-emerald-400', accent: 'bg-emerald-500' },
};

const WeeklyPlanner = () => {
  const { dbUser } = useAuth();
  const navigate = useNavigate();
  const today = new Date();
  const [currentDate, setCurrentDate] = useState(today);
  const [weekData, setWeekData] = useState({});
  const [subjects, setSubjects] = useState([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [selectedDay, setSelectedDay] = useState(null);

  const getWeekStart = (date) => {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1);
    return new Date(d.setDate(diff));
  };

  const weekStart = getWeekStart(currentDate);
  const weekDays = Array.from({ length: 7 }, (_, i) => {
    const d = new Date(weekStart);
    d.setDate(weekStart.getDate() + i);
    return d;
  });

  useEffect(() => {
    if (!dbUser?.id) return;
    const fetchData = async () => {
      try {
        // Find week start date for API
        const weekStartDateStr = weekStart.toISOString().split('T')[0];
        const res = await getWeeklyPlan(dbUser.id, weekStartDateStr);

        // Group by day format 'Mon', 'Tue' etc
        const groupedData = {};
        if (Array.isArray(res.data)) {
          res.data.forEach(plan => {
            const dateObj = new Date(plan.date);
            const dayKey = dateObj.toLocaleDateString('en-US', { weekday: 'short' });
            if (!groupedData[dayKey]) groupedData[dayKey] = [];
            groupedData[dayKey].push(plan);
          });
        }
        setWeekData(groupedData);

        // Fetch subjects for dropdown if examId is available
        if (dbUser.examId) {
            const subRes = await getSubjects(dbUser.examId);
            setSubjects(Array.isArray(subRes.data) ? subRes.data : []);
        } else {
            setSubjects(Object.keys(DEFAULT_SUBJECT_COLORS).map(s => ({id: s, name: s})));
        }

      } catch (error) {
        console.error('Error fetching weekly data:', error);
      }
    };
    fetchData();
  }, [dbUser?.id, weekStart.toISOString()]);

  const prevWeek = () => {
    const d = new Date(currentDate);
    d.setDate(d.getDate() - 7);
    setCurrentDate(d);
  };

  const nextWeek = () => {
    const d = new Date(currentDate);
    d.setDate(d.getDate() + 7);
    setCurrentDate(d);
  };

  const goToToday = () => setCurrentDate(new Date());

  const openAddModal = (day) => {
    setSelectedDay(day);
    setShowAddModal(true);
  };

  const addTopic = async (subjectName, topic, timeFrom, timeTo) => {
    if (!selectedDay || !subjectName || !topic.trim() || !dbUser?.id) return;
    const dayKey = selectedDay.toLocaleDateString('en-US', { weekday: 'short' });
    const dateStr = selectedDay.toISOString().split('T')[0];

    const newPlan = {
      subject: subjectName,
      topic,
      timeFrom: timeFrom || null,
      timeTo: timeTo || null,
      date: dateStr
    };

    try {
      const res = await createWeeklyPlanApi(dbUser.id, newPlan);
      setWeekData(prev => ({
        ...prev,
        [dayKey]: [...(prev[dayKey] || []), res.data],
      }));
    } catch (error) {
      console.error('Error creating weekly plan:', error);
    }

    setShowAddModal(false);
    setSelectedDay(null);
  };

  const removeTopic = async (dayKey, planId, index) => {
    if(confirm('Delete this plan?')) {
      try {
        await deleteWeeklyPlanApi(planId);
        setWeekData(prev => ({
          ...prev,
          [dayKey]: prev[dayKey].filter(p => p.id !== planId),
        }));
      } catch (error) {
         console.error('Error deleting weekly plan:', error);
      }
    }
  };

  const goToDailyPlanner = (date) => {
    navigate(`/daily?date=${date.toISOString().split('T')[0]}`);
  };

  const weekRange = `${weekStart.toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })} - ${weekDays[6].toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })}`;

  return (
    <div className="space-y-6">

      {/* Week Navigation */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <button onClick={goToToday} className="text-xs font-semibold text-blue-400 hover:text-blue-300 px-3 py-1.5 rounded-lg hover:bg-blue-500/10 border border-blue-500/20 transition-all">Today</button>
          <div className="flex items-center gap-2 bg-white dark:bg-white/[0.03] border border-slate-200 dark:border-white/[0.06] px-3 py-1.5 rounded-lg">
            <button onClick={prevWeek} className="text-slate-500 hover:text-slate-900 dark:hover:text-white transition-colors"><ChevronLeft size={16} /></button>
            <span className="text-sm font-bold text-slate-900 dark:text-white min-w-[140px] text-center">{weekRange}</span>
            <button onClick={nextWeek} className="text-slate-500 hover:text-slate-900 dark:hover:text-white transition-colors"><ChevronRight size={16} /></button>
          </div>
        </div>
      </div>

      {/* Week Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-7 gap-4" style={{ gridTemplateColumns: 'repeat(auto-fit, minmax(0, 1fr))' }}>
        {weekDays.map((date, i) => {
          const dayKey = date.toLocaleDateString('en-US', { weekday: 'short' });
          const topics = weekData[dayKey] || [];
          const isToday = date.toDateString() === new Date().toDateString();
          const isPast = date < new Date() && !isToday;

          return (
            <div key={i} className={`bg-white dark:bg-[#0a0f1e]/60 border rounded-2xl overflow-hidden transition-all duration-300 flex flex-col min-w-0 ${isToday ? 'border-blue-500/50 shadow-xl shadow-blue-500/20 ring-2 ring-blue-500/20' : 'border-slate-200 dark:border-white/[0.06] hover:border-slate-300 dark:hover:border-white/[0.09]'} ${isPast ? 'opacity-60' : ''}`}>

              <div className={`px-4 py-3 border-b flex items-center justify-between ${isToday ? 'bg-blue-500/10 border-blue-500/20' : 'border-slate-100 dark:border-white/[0.05]'}`}>
                <div className="min-w-0">
                  <div className={`text-xs font-black uppercase tracking-wider ${isToday ? 'text-blue-400' : 'text-slate-500'}`}>{dayKey}</div>
                  <div className={`text-2xl font-black leading-none mt-1 ${isToday ? 'text-slate-900 dark:text-white' : 'text-slate-700 dark:text-slate-300'}`}>{date.getDate()}</div>
                  <div className="text-[10px] text-slate-400 dark:text-slate-600 font-medium mt-0.5">{date.toLocaleDateString('en-US', { month: 'short' })}</div>
                </div>
                {isToday && <div className="flex flex-col items-center gap-1"><div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse" /><span className="text-[9px] font-bold text-blue-400 uppercase tracking-wider">Now</span></div>}
              </div>

              <div className="flex-1 p-3 space-y-2 min-h-[250px] max-h-[400px] overflow-y-auto min-w-0">
                {topics.map((item, idx) => {
                  const colors = DEFAULT_SUBJECT_COLORS[item.subject] || DEFAULT_SUBJECT_COLORS['Algorithms'];
                  const hasTime = item.timeFrom && item.timeTo;
                  return (
                    <div key={item.id || idx} className={`group p-3 rounded-xl border ${colors.bg} ${colors.border} hover:scale-[1.02] transition-all duration-200 cursor-pointer relative min-w-0`}>
                      {hasTime && <div className="flex items-center gap-1.5 mb-2"><Clock size={10} className={colors.text} /><span className={`text-[10px] font-bold ${colors.text} truncate`}>{item.timeFrom} - {item.timeTo}</span></div>}
                      <div className="flex items-center gap-2 mb-1.5 min-w-0"><div className={`w-1 h-4 rounded-full shrink-0 ${colors.accent}`} /><span className={`text-xs font-bold ${colors.text} truncate`}>{item.subject}</span></div>
                      <p className="text-xs text-slate-600 dark:text-slate-300 leading-relaxed pl-3 line-clamp-2 break-words">{item.topic}</p>
                      <button onClick={(e) => { e.stopPropagation(); removeTopic(dayKey, item.id, idx); }} className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 w-5 h-5 rounded-lg bg-red-500/20 border border-red-500/30 flex items-center justify-center text-red-400 hover:bg-red-500/30 transition-all duration-200"><X size={10} /></button>
                    </div>
                  );
                })}
                {topics.length === 0 && <div className="flex items-center justify-center h-full text-slate-400 dark:text-slate-700"><div className="text-center"><CalendarIcon size={24} className="mx-auto mb-2 opacity-30" /><p className="text-xs italic">No topics</p></div></div>}
              </div>

              <div className="px-3 pb-3 flex gap-2 border-t border-slate-100 dark:border-white/[0.05] pt-3">
                <button onClick={() => openAddModal(date)} className="flex-1 py-2 px-3 rounded-lg bg-slate-50 dark:bg-white/[0.03] border border-slate-200 dark:border-white/[0.06] text-xs font-semibold text-slate-500 dark:text-slate-400 hover:text-blue-500 dark:hover:text-blue-400 hover:bg-blue-500/10 hover:border-blue-500/30 transition-all duration-200 flex items-center justify-center gap-1.5"><Plus size={14} /> Add</button>
                <button onClick={() => goToDailyPlanner(date)} className="py-2 px-3 rounded-lg bg-blue-500/10 border border-blue-500/30 text-xs font-semibold text-blue-400 hover:bg-blue-500/20 transition-all duration-200 flex items-center gap-1"><ArrowRight size={14} /></button>
              </div>
            </div>
          );
        })}
      </div>

      {/* Add Topic Modal */}
      {showAddModal && selectedDay && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4" onClick={() => setShowAddModal(false)}>
          <div className="bg-white dark:bg-[#0f1629] border border-slate-200 dark:border-white/[0.1] rounded-2xl p-6 max-w-md w-full shadow-2xl" onClick={e => e.stopPropagation()}>
            <h3 className="text-lg font-bold text-slate-900 dark:text-white mb-1">Add Topic</h3>
            <p className="text-sm text-slate-500 mb-4">{selectedDay.toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'long' })}</p>
            <form onSubmit={e => {
              e.preventDefault();
              addTopic(e.target.subject.value, e.target.topic.value, e.target.timeFrom.value, e.target.timeTo.value);
              e.target.reset();
            }}>
              <div className="space-y-3">
                <select name="subject" required className="w-full px-4 py-3 rounded-xl bg-white dark:bg-white/[0.05] border border-slate-300 dark:border-white/[0.1] text-slate-900 dark:text-slate-200 outline-none focus:border-blue-500/50">
                  <option value="">Select subject</option>
                  {subjects.map(subject => (
                    <option key={subject.id} value={subject.name}>{subject.name}</option>
                  ))}
                </select>
                <input name="topic" type="text" placeholder="Enter topic name..." required className="w-full px-4 py-3 rounded-xl bg-white dark:bg-white/[0.05] border border-slate-300 dark:border-white/[0.1] text-slate-900 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-600 outline-none focus:border-blue-500/50" />
                <div className="border-t border-slate-100 dark:border-white/[0.05] pt-3 mt-3">
                  <p className="text-xs text-slate-500 mb-2 flex items-center gap-2"><Clock size={12} />Time slot (optional)</p>
                  <div className="grid grid-cols-2 gap-3">
                    <input name="timeFrom" type="time" className="px-4 py-3 rounded-xl bg-white dark:bg-white/[0.05] border border-slate-300 dark:border-white/[0.1] text-slate-900 dark:text-slate-200 outline-none focus:border-blue-500/50" />
                    <input name="timeTo" type="time" className="px-4 py-3 rounded-xl bg-white dark:bg-white/[0.05] border border-slate-300 dark:border-white/[0.1] text-slate-900 dark:text-slate-200 outline-none focus:border-blue-500/50" />
                  </div>
                </div>
              </div>
              <div className="flex gap-3 mt-4">
                <button type="button" onClick={() => setShowAddModal(false)} className="flex-1 py-2 px-4 rounded-lg bg-slate-100 dark:bg-white/[0.05] text-slate-500 dark:text-slate-400 border border-slate-200 dark:border-white/[0.1] hover:bg-slate-200 dark:hover:bg-white/[0.08] font-medium transition-all">Cancel</button>
                <button type="submit" className="flex-1 py-2 px-4 rounded-lg bg-blue-500 text-white font-bold hover:bg-blue-600 transition-all">Add Topic</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

